// plus an AND gate feeding back into the register.
module TopModule(input  clk,
                 input  w,
                 input  R,
                 input  E,
                 input  L,
                 output Q);
    reg [1:0] D;
    wire Q_next;
    reg [1:0] D_next;
    assign Q_next = D[0];
    always @(*) begin
        D_next[0] = Q_next;
        D_next[1] = D[0] & E;
    end
    always @(posedge clk) begin
        if (L) D <= {1'b0, R};
        else D <= D_next;
    end
endmodule

